PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;

CREATE TABLE IF NOT EXISTS business_settings (id INTEGER PRIMARY KEY CHECK (id = 1), business_name TEXT NOT NULL, business_type TEXT NOT NULL, logo_path TEXT, primary_color TEXT NOT NULL, phone TEXT, address TEXT, tax_number TEXT, currency TEXT NOT NULL DEFAULT 'LYD', decimals INTEGER NOT NULL DEFAULT 3, language TEXT NOT NULL DEFAULT 'ar', rtl INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('admin','cashier')), is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS units (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, sku TEXT NOT NULL UNIQUE, barcode TEXT UNIQUE, category_id INTEGER REFERENCES categories(id), description TEXT, image TEXT, unit_id INTEGER REFERENCES units(id), purchase_price_minor INTEGER NOT NULL DEFAULT 0, retail_price_minor INTEGER NOT NULL DEFAULT 0, wholesale_price_minor INTEGER NOT NULL DEFAULT 0, minimum_stock INTEGER NOT NULL DEFAULT 0, track_inventory INTEGER NOT NULL DEFAULT 1, notes TEXT, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS product_variants (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id), name TEXT NOT NULL, sku TEXT NOT NULL UNIQUE, barcode TEXT UNIQUE, stock_quantity INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS product_units (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id), unit_id INTEGER NOT NULL REFERENCES units(id), conversion_to_base INTEGER NOT NULL CHECK (conversion_to_base > 0), UNIQUE(product_id, unit_id));
CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, phone TEXT, additional_phone TEXT, city TEXT, address TEXT, opening_balance_minor INTEGER NOT NULL DEFAULT 0, notes TEXT, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suppliers (id INTEGER PRIMARY KEY AUTOINCREMENT, supplier_number TEXT NOT NULL UNIQUE, name TEXT NOT NULL, contact_person TEXT, phone TEXT, additional_phone TEXT, city TEXT, address TEXT, tax_number TEXT, account_reference TEXT, opening_balance_minor INTEGER NOT NULL DEFAULT 0, notes TEXT, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sales (id INTEGER PRIMARY KEY AUTOINCREMENT, invoice_number TEXT NOT NULL UNIQUE, customer_id INTEGER REFERENCES customers(id), subtotal_minor INTEGER NOT NULL, discount_minor INTEGER NOT NULL DEFAULT 0, total_minor INTEGER NOT NULL, paid_minor INTEGER NOT NULL DEFAULT 0, payment_status TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'completed', cashier_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, cancelled_at TEXT, cancelled_by INTEGER, cancellation_reason TEXT);
CREATE TABLE IF NOT EXISTS sale_items (id INTEGER PRIMARY KEY AUTOINCREMENT, sale_id INTEGER NOT NULL REFERENCES sales(id), product_id INTEGER NOT NULL REFERENCES products(id), variant_id INTEGER REFERENCES product_variants(id), unit_id INTEGER REFERENCES units(id), quantity INTEGER NOT NULL CHECK(quantity > 0), unit_price_minor INTEGER NOT NULL, purchase_cost_at_sale_minor INTEGER NOT NULL, discount_minor INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sale_payments (id INTEGER PRIMARY KEY AUTOINCREMENT, sale_id INTEGER NOT NULL REFERENCES sales(id), method TEXT NOT NULL, amount_minor INTEGER NOT NULL CHECK(amount_minor >= 0), reference TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS purchases (id INTEGER PRIMARY KEY AUTOINCREMENT, invoice_number TEXT NOT NULL UNIQUE, supplier_id INTEGER NOT NULL REFERENCES suppliers(id), subtotal_minor INTEGER NOT NULL, discount_minor INTEGER NOT NULL DEFAULT 0, total_minor INTEGER NOT NULL, paid_minor INTEGER NOT NULL DEFAULT 0, payment_status TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'completed', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS purchase_items (id INTEGER PRIMARY KEY AUTOINCREMENT, purchase_id INTEGER NOT NULL REFERENCES purchases(id), product_id INTEGER NOT NULL REFERENCES products(id), variant_id INTEGER REFERENCES product_variants(id), quantity INTEGER NOT NULL, unit_cost_minor INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS inventory_transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, product_id INTEGER NOT NULL REFERENCES products(id), variant_id INTEGER REFERENCES product_variants(id), type TEXT NOT NULL, quantity INTEGER NOT NULL, quantity_before INTEGER NOT NULL, quantity_after INTEGER NOT NULL, reference_type TEXT, reference_id INTEGER, notes TEXT, user_id INTEGER REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customer_transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INTEGER NOT NULL REFERENCES customers(id), type TEXT NOT NULL, amount_minor INTEGER NOT NULL, balance_after_minor INTEGER NOT NULL, reference_type TEXT, reference_id INTEGER, notes TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS supplier_transactions (id INTEGER PRIMARY KEY AUTOINCREMENT, supplier_id INTEGER NOT NULL REFERENCES suppliers(id), type TEXT NOT NULL, amount_minor INTEGER NOT NULL, balance_after_minor INTEGER NOT NULL, reference_type TEXT, reference_id INTEGER, notes TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS expenses (id INTEGER PRIMARY KEY AUTOINCREMENT, category TEXT NOT NULL, amount_minor INTEGER NOT NULL CHECK(amount_minor >= 0), description TEXT NOT NULL, expense_date TEXT NOT NULL, user_id INTEGER REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attachments (id INTEGER PRIMARY KEY AUTOINCREMENT, entity_type TEXT NOT NULL, entity_id INTEGER NOT NULL, path TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS backup_history (id INTEGER PRIMARY KEY AUTOINCREMENT, path TEXT NOT NULL, created_at TEXT NOT NULL, user_id INTEGER REFERENCES users(id));
CREATE INDEX IF NOT EXISTS idx_products_name ON products(name); CREATE INDEX IF NOT EXISTS idx_products_barcode ON products(barcode); CREATE INDEX IF NOT EXISTS idx_products_sku ON products(sku); CREATE INDEX IF NOT EXISTS idx_sales_created_at ON sales(created_at); CREATE INDEX IF NOT EXISTS idx_sales_customer_id ON sales(customer_id); CREATE INDEX IF NOT EXISTS idx_inventory_product_id ON inventory_transactions(product_id); CREATE INDEX IF NOT EXISTS idx_customer_transactions_customer_id ON customer_transactions(customer_id); CREATE INDEX IF NOT EXISTS idx_supplier_transactions_supplier_id ON supplier_transactions(supplier_id);
